  return {...summary,cess,books,variance,amendments,readiness,documentRanges,outwardSections,formats:this.s.db.prepare("SELECT key,payload FROM app_settings WHERE key LIKE 'gstFormat:%'").all().map(r=>({key:r.key,id:JSON.parse(r.payload as string).id,version:JSON.parse(r.payload as string).version,kind:JSON.parse(r.payload as string).kind})),tracker,imports2B:this.s.db.prepare('SELECT id,period,hash,at FROM gstr2b_imports WHERE period=? ORDER BY at DESC').all(period),purchases:this.s.db.prepare('SELECT * FROM purchase_documents WHERE date LIKE ?').all(period+'%')};
